        // has not been handed out anywhere else yet.
        let new_node = unsafe {
            NonNull::new_unchecked(Box::into_raw(Box::new(Node {
                element,
                next: None,
                prev: None,
            })))
        };

        match self.cur {
            Some(cur) => {
